export const PESOS_TIPICOS: { v: string; t: string; kg: number }[];
export const ALTURAS_TIPICAS: { t: string; m: number; d: string }[];
export const TOLERANCIA_MEDIDAS: number;
export const DATOS: { k: string; t: string; peso: number; clave?: boolean }[];
